There is a critical bug in the cycle resolution and caching logic of `resolve_network`. When a cycle is detected (e.g., `A -> B -> C -> B`), the intermediate/incomplete state of `B` is cached as an empty or partially resolved set in `self._network_cache['B']`. When `C` queries `B`, it copies this incomplete set. Once `C` finishes resolving, it caches its incomplete result in `self._network_cache['C']`. Later, `B` continues resolving its other members (e.g., concrete IPs) and updates its own set, but `C`'s cached result is never updated and remains permanently stale and incomplete. Any subsequent queries for `C` will return this incomplete cached result, missing the members of `B` that were resolved after `C` queried `B`.

To fix this, we can track incomplete nodes during cycle resolution and remove them from the cache once the top-level call finishes.

```python
    def resolve_network(
        self,
        token: Union[str, ipaddress.IPv4Address, ipaddress.IPv4Network],
        visited: Optional[Set[str]] = None,
        incomplete: Optional[Set[str]] = None,
    ) -> Set[Union[ipaddress.IPv4Address, ipaddress.IPv4Network]]:
        if visited is None:
            visited = set()
        if incomplete is None:
            incomplete = set()
        is_top_level = len(visited) == 0

        if isinstance(token, (ipaddress.IPv4Address, ipaddress.IPv4Network)):
            return {token}
        if isinstance(token, str):
            cache_key = token
            cached = self._network_cache.get(cache_key)
            if cached is not None:
                return set(cached)
            token_lower = token.lower()
            if token_lower in ('any', 'any4', 'any-ipv4'):
                result = {ipaddress.ip_network('0.0.0.0/0')}
                self._network_cache[cache_key] = set(result)
                return result
            if token_lower in ('any6', 'any-ipv6'):
                try: 
                    result = {ipaddress.ip_network('::/0')}
                except (ValueError, TypeError):
                    result = set()
                self._network_cache[cache_key] = set(result)
                return result
            if token in self.network_objects:
                nets = set(self.network_objects[token])
                self._network_cache[cache_key] = set(nets)
                return nets
            if token in self.network_object_groups:
                if token in visited:
                    incomplete.update(visited)
                    cached_cycle = self._network_cache.get(cache_key)
                    return set(cached_cycle) if cached_cycle is not None else set()
                visited.add(token)
                resolved: Set[Union[ipaddress.IPv4Address, ipaddress.IPv4Network]] = set()
                self._network_cache[cache_key] = resolved
                for m in self.network_object_groups[token]:
                    if isinstance(m, dict):
                        if 'group-object' in m:
                            dep = m['group-object']
                            resolved.update(self.resolve_network(dep, visited, incomplete))
                            if dep in incomplete:
                                incomplete.add(token)
                        elif 'object' in m:
                            dep = m['object']
                            resolved.update(self.resolve_network(dep, visited, incomplete))
                            if dep in incomplete:
                                incomplete.add(token)
                    elif isinstance(m, (ipaddress.IPv4Address, ipaddress.IPv4Network)):
                        resolved.add(m)
                visited.discard(token)

                if is_top_level:
                    for key in incomplete:
                        self._network_cache.pop(key, None)

                return set(resolved)
            try: 
                result = {to_ip_network(token)}
            except (ValueError, TypeError):
                result = set()
            self._network_cache[cache_key] = set(result)
            return result
        return set()
```

